                            grid[nx][ny] == color and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        stack.append((nx, ny))

            r0, r1 = min(x for x, y in cells), max(x for x, y in cells)
            c0, c1 = min(y for x, y in cells), max(y for x, y in cells)
            occupied = set(cells)
            is_frame = (
                r1 > r0 and c1 > c0 and
                all((x, y) in occupied
                    for x in range(r0, r1 + 1)
                    for y in range(c0, c1 + 1)
                    if x in (r0, r1) or y in (c0, c1))
            )
            objects.append((cells, color, -1 if is_frame else 1))

    # The two classes pass through one another; only objects moving in the
    # same direction constrain each other's movement.
    moved_objects = []
    for direction in (-1, 1):
        layer = [[0] * w for _ in range(h)]
        group = [obj for obj in objects if obj[2] == direction]
        if direction == -1:
            group.sort(key=lambda obj: min(r for r, c in obj[0]))
        else:
            group.sort(key=lambda obj: -max(r for r, c in obj[0]))

        for cells, color, _ in group:
            shift = 0
            while True:
                trial = [(r + shift + direction, c) for r, c in cells]
                if any(r < 0 or r >= h or layer[r][c] != 0 for r, c in trial):
                    break
                shift += direction
            placed = [(r + shift, c) for r, c in cells]
            for r, c in placed:
                layer[r][c] = color
            moved_objects.append((placed, color))

    out = [[0] * w for _ in range(h)]
    for cells, color in moved_objects:
        for r, c in cells:
            out[r][c] = color
    return out
